package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock reports the current time. It is injectable for testing.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// RealClock returns a Clock backed by time.Now.
func RealClock() Clock { return realClock{} }

// Limiter is a token-bucket rate limiter. It is safe for concurrent use.
type Limiter struct {
	mu       sync.Mutex
	rate     float64   // tokens per second
	burst    float64   // bucket capacity
	tokens   float64   // current tokens
	last     time.Time // last refill time
	clock    Clock
}

// New creates a Limiter that refills rate tokens per second, up to burst.
func New(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, errors.New("ratelimit: rate must be > 0")
	}
	if burst <= 0 {
		return nil, errors.New("ratelimit: burst must be > 0")
	}
	if clock == nil {
		return nil, errors.New("ratelimit: clock must not be nil")
	}
	return &Limiter{
		rate:   rate,
		burst:  float64(burst),
		tokens: float64(burst),
		last:   clock.Now(),
		clock:  clock,
	}, nil
}

// AllowN reports whether n tokens may be consumed at time now.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	if now.Before(l.last) {
		now = l.last // guard against clock going backwards
	}
	elapsed := now.Sub(l.last).Seconds()
	l.tokens = min(l.burst, l.tokens+elapsed*l.rate)
	l.last = now

	if float64(n) > l.tokens {
		return false
	}
	l.tokens -= float64(n)
	return true
}

// Allow reports whether one token may be consumed now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.clock.Now(), 1)
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
