// Package ratelimit implements a concurrency-safe token-bucket rate limiter.
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// RealClock returns a Clock backed by the wall clock.
func RealClock() Clock { return realClock{} }

// Limiter is a concurrency-safe token-bucket rate limiter.
// A Limiter value must not be copied after first use.
type Limiter struct {
	mu       sync.Mutex
	clock    Clock
	rate     float64   // tokens per second
	burst    float64   // bucket capacity
	tokens   float64
	last     time.Time // last refill time
}

// New creates a Limiter that refills rate tokens per second, with a maximum
// capacity of burst tokens. The bucket starts full.
func New(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, errors.New("ratelimit: rate must be > 0")
	}
	if burst <= 0 {
		return nil, errors.New("ratelimit: burst must be > 0")
	}
	if clock == nil {
		clock = RealClock()
	}
	now := clock.Now()
	return &Limiter{
		clock:  clock,
		rate:   rate,
		burst:  float64(burst),
		tokens: float64(burst),
		last:   now,
	}, nil
}

// Allow reports whether a single token is available.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available at time now, refilling the
// bucket first. It never blocks.
func (l *Limiter) AllowN(n int) bool {
	if n <= 0 {
		return true
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.burst {
			l.tokens = l.burst
		}
		l.last = now
	}
	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Tokens returns the current number of available tokens (for observability).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	elapsed := l.clock.Now().Sub(l.last).Seconds()
	t := l.tokens + elapsed*l.rate
	if t > l.burst {
		t = l.burst
	}
	return t
}
