// Package ratelimit implements a concurrency-safe token-bucket rate limiter.
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock reports the current time. It allows tests to inject a fake clock.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// RealClock returns a Clock backed by time.Now.
func RealClock() Clock { return realClock{} }

// Limiter is a concurrency-safe token-bucket rate limiter.
// A Limiter must be created by New and is safe for concurrent use.
type Limiter struct {
	mu       sync.Mutex
	tokens   float64
	last     time.Time
	capacity float64
	rate     float64 // tokens per second
	clock    Clock
}

// Errors returned by New.
var (
	ErrNonPositiveRate     = errors.New("ratelimit: rate must be > 0")
	ErrNonPositiveCapacity = errors.New("ratelimit: capacity must be > 0")
	ErrNilClock            = errors.New("ratelimit: clock must not be nil")
)

// New returns a Limiter with the given burst capacity and refill rate
// (tokens per second), starting full. The clock is injectable for testing.
func New(capacity int, rate float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 {
		return nil, ErrNonPositiveCapacity
	}
	if rate <= 0 {
		return nil, ErrNonPositiveRate
	}
	if clock == nil {
		return nil, ErrNilClock
	}
	return &Limiter{
		tokens:   float64(capacity),
		last:     clock.Now(),
		capacity: float64(capacity),
		rate:     rate,
		clock:    clock,
	}, nil
}

// refill advances the bucket to time now, adding accrued tokens.
// The caller must hold l.mu.
func (l *Limiter) refill(now time.Time) {
	if now.After(l.last) {
		elapsed := now.Sub(l.last).Seconds()
		l.tokens = min(l.capacity, l.tokens+elapsed*l.rate)
		l.last = now
	}
}

// AllowN reports whether n tokens may be consumed at time now.
// If allowed, the tokens are consumed; otherwise the bucket is unchanged.
// n must be non-negative; a negative n returns false.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(now)
	if l.tokens < float64(n) {
		return false
	}
	l.tokens -= float64(n)
	return true
}

// Allow reports whether one token may be consumed now.
func (l *Limiter) Allow() bool { return l.AllowN(l.clock.Now(), 1) }

// Tokens returns the current number of available tokens, refilling first.
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(l.clock.Now())
	return l.tokens
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
